"""CLI entrypoint for generating, verifying, or cleaning autogenerated files in ``docs/``."""

import sys
from collections.abc import Sequence
from typing import Annotated, Self

from pydantic import Field, model_validator
from pydantic_settings import BaseSettings, SettingsConfigDict

from docs_macros.env import (
    DEFAULT_GENERATION_PATHS,
    DocsGenerationPaths,
    clean_generated_docs,
    sync_generated_docs,
)
from docs_macros.formatting import rel_posix


class DocsMacrosCliSettings(BaseSettings):
    """Frozen CLI settings for generating, verifying, or cleaning autogenerated files in ``docs/``."""

    model_config: SettingsConfigDict = SettingsConfigDict(
        frozen=True,
        cli_prog_name="python -m docs_macros",
        cli_implicit_flags=True,
        extra="forbid",
    )

    check: Annotated[
        bool,
        Field(
            default=False,
            description="Verify all autogenerated files in docs/ exist and are up to date without modifying disk.",
        ),
    ]
    clean: Annotated[
        bool,
        Field(
            default=False,
            description="Remove all autogenerated Markdown stubs and published schemas from docs/.",
        ),
    ]

    @model_validator(mode="after")
    def _validate_mutually_exclusive_modes(self) -> Self:
        """Ensure ``--check`` and ``--clean`` are not enabled simultaneously.

        :return: Validated settings instance.
        :rtype: Self
        """
        if self.check and self.clean:
            msg = "--check and --clean cannot be used together."
            raise ValueError(msg)
        return self


def main(
    argv: Sequence[str] | None = None,
    *,
    paths: DocsGenerationPaths = DEFAULT_GENERATION_PATHS,
    include_static_pages: bool = True,
) -> int:
    """Generate, verify, or remove autogenerated files in ``docs/``.

    :param argv: Optional CLI argument sequence (defaults to ``sys.argv[1:]``).
    :type argv: Sequence[str] | None
    :param paths: Filesystem roots for ``docs/``, specs, package schemas, and Jinja2 templates.
    :type paths: DocsGenerationPaths
    :param include_static_pages: Whether to include ``cli_reference.md`` and ``bundled_schemas.md``.
    :type include_static_pages: bool
    :return: Process exit code (``0`` on success, ``1`` when ``--check`` detects missing or drifted files).
    :rtype: int
    """
    settings = DocsMacrosCliSettings(_cli_parse_args=list(argv) if argv is not None else True)
    if settings.clean:
        removed = clean_generated_docs(paths)
        for path in removed:
            sys.stdout.write(f"Removed {path.as_posix()}\n")
        if not removed:
            sys.stdout.write("No autogenerated documentation files present to remove.\n")
        return 0

    result = sync_generated_docs(
        paths,
        include_static_pages=include_static_pages,
        check=settings.check,
    )
    if settings.check:
        if result.drifted_paths:
            for path in result.drifted_paths:
                label = rel_posix(path, paths.repo_root) if path.is_relative_to(paths.repo_root) else path.as_posix()
                sys.stderr.write(f"Missing or out-of-date autogenerated doc file: {label}\n")
            sys.stderr.write("Run 'uv run python -m docs_macros' to generate documentation stubs and schemas.\n")
            return 1
        sys.stdout.write(f"Verified {len(result.expected_paths)} autogenerated documentation file(s) in sync.\n")
        return 0

    for path in result.written_paths:
        sys.stdout.write(f"Wrote {path.as_posix()}\n")
    for path in result.removed_paths:
        sys.stdout.write(f"Removed stale {path.as_posix()}\n")
    if not result.written_paths and not result.removed_paths:
        sys.stdout.write(f"All {len(result.expected_paths)} autogenerated documentation file(s) already up to date.\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
